package com.grouptwo.ourtimes;

import android.os.Bundle;
import android.widget.Toast;

import androidx.appcompat.app.AppCompatActivity;
import androidx.navigation.NavController;
import androidx.navigation.fragment.NavHostFragment;

import com.grouptwo.ourtimes.databinding.ActivityMainBinding;

public class MainActivity extends AppCompatActivity {
    private ActivityMainBinding binding;
    private NavController navController;

    // Autogenerated edge-to-edge code removed as it provides a poor experience with 3-button navbars
    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);

        // Set layout via ViewBinding
        binding = ActivityMainBinding.inflate(getLayoutInflater());
        setContentView(binding.getRoot());

        // Set up Navigation controller for navigating between Fragments
        NavHostFragment navHostFragment = (NavHostFragment) getSupportFragmentManager().findFragmentById(R.id.nav_host_fragment);
        if (navHostFragment != null) {
            navController = navHostFragment.getNavController();
        } else {
            // The app can't run without NavHostFragment so we exit gracefully (and inform us or the user of the error)
            String noHostFragmentError = "ERROR: nav_host_fragment is null";
            Toast.makeText(this, noHostFragmentError, Toast.LENGTH_LONG).show();
            finishAndRemoveTask();
        }
    }
}